function previewFile(e,t){const n=document.getElementById(t),i=e.files[0];if(i){const e=new FileReader;e.onload=function(e){n.innerHTML=`<img src="${e.target.result}" alt="Uploaded Image" />`,n.style.display="block"},e.readAsDataURL(i)}else n.innerHTML="",n.style.display="none"}function goBack(){history.back()}document.addEventListener("DOMContentLoaded",(()=>{document.querySelectorAll("img").forEach((e=>{let t=e.getAttribute("src");if(!t.includes(".webp")){let n=t.replace(/\.(jpg|jpeg|png)$/i,".webp");e.setAttribute("src",n)}e.setAttribute("loading","lazy"),e.onload=function(){e.width>800&&(e.width=800)}}))}));